INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (1, 1, 0, 160, 0.029, 1, 101, 0, 105, 122601, 1.5, 1, 110, "仲間と夏を楽しむ、夏海の魔法士。自分を変えたいという固い決意で、障害物を無効化して走り続ける。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (2, 2, 0, 120, 0.014, 3, 102, 1, 111, 122401, 2.5, 0, 105, "太陽よりも輝く、夏海の元気娘。　持ち前の身体能力で、どんなコースも柔軟に対応し、駆け抜ける。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (3, 3, 1, 350, 0.017, 2, 103, 0, 105, 122501, 2.5, 0, 110, "波打ち際に煌めく、夏海の剣士。　日々の鍛錬で鍛えた脚で、長い距離も速度を落とさず走り切る。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (4, 4, 0, 130, 0.016, 3, 104, 1, 105, 107501, 1.5, 0, 110, "海の幸に目がない、渚のお姫様。　『王家の装備』の力を解放し、障害物をものともせず前へと進む。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (5, 5, 0, 160, 0.014, 1, 105, 0, 105, 107601, 2.5, 1, 110, "海でも主さまをお世話する、白浜の巫女。精霊の力で自身を加速させ、誰よりも速くゴールを目指す。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (6, 6, 1, 255, 0.029, 2, 106, 0, 103, 107801, 3.5, 0, 120, "水着姿を恥じらう、ツンデレ猫娘。お得意の魔法で、対戦相手の走りを妨害し、レースを有利に進める。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (7, 7, 0, 160, 0.013, 1, 107, 0, 103, 110601, 3.5, 1, 120, "優雅に浜を駆ける、真夏のマホ姫。しゃなりしゃなりと、雅な身のこなしで障害物を跳び越えていく。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (8, 8, 1, 350, 0.014, 2, 108, 0, 103, 110401, 2.5, 0, 110, "浜の平和を守る、真夏の狼娘。　　獣人の強靭なスタミナで、レース　後半にスパートをかける。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (9, 9, 0, 130, 0.012, 3, 109, 1, 100, 110501, 1.5, 0, 105, "浜に力強く舞う、真夏の南国娘。　レースの喧噪の中でも精神を乱さず後半に大きな捲りを見せる。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (10, 10, 0, 200, 0.014, 1, 110, 0, 103, 115701, 2.5, 1, 105, "浜の事件を嗅ぎ付けた、真夏の　　名探偵。高い推理力と魔法で、的確に対戦相手の走りを乱す。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (11, 11, 1, 350, 0.071, 2, 111, 0, 103, 113601, 2.5, 0, 105, "再び鎧を脱いだ、灼熱の騎士団長。実戦で培った判断力で、瞬時にバリアを展開し、障害物を無力化する。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (12, 12, 0, 130, 0.014, 3, 112, 1, 103, 107901, 1.5, 0, 120, "水が苦手な、海辺の気まぐれ猫娘。浜に現れた美少女義賊は、対戦相手のスピードを奪いとる。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (13, 13, 0, 200, 0.022, 2, 113, 0, 105, 108001, 1.5, 1, 110, "バカンスも効率第一な、海の傭兵。レースでも最高効率を求め、どんな状況でも隙のない走りを見せる。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (14, 14, 0, 160, 0.031, 1, 114, 0, 108, 110301, 2.5, 1, 110, "真夏の太陽が良く似合う、海辺の　サレンママ。多才で器用、どんな　障害物もエレガントに越えていく。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (15, 15, 0, 130, 0.036, 1, 115, 1, 105, 107701, 0.5, 0, 110, "海に嵐を呼ぶ夏のドジっ娘メイド。日頃から災難に慣れており、多少　のトラブルには動じたりしない。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (16, 16, 1, 350, 0.048, 2, 116, 0, 95, 113101, 3.5, 0, 110, "粋な夏を愉しむ、若夏の姉御。　　流麗な身体捌きで、始・継・終と、UBを重ねるごとに、加速する。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (17, 17, 0, 130, 0.043, 3, 117, 1, 105, 113301, 1.5, 0, 105, "夏のトキメキに触れた、オタク魔法少女。多彩な魔法を操り、少しずつ他の走者の速度を落とし続ける。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (18, 18, 0, 130, 0.018, 2, 118, 1, 95, 113201, 1.5, 0, 105, "海獄に降臨せし、真夏の冥姫。　　レース後半に魔力を全解放し、　　蒼き疾風と成りて浜を駆け抜ける。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (19, 19, 0, 160, 0.021, 2, 119, 0, 108, 117001, 2.5, 1, 110, "夏の夕を火花で彩る、渚の壊し屋。『壊し屋』の異名と過激な愛情は、対戦相手にプレッシャーを与える。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (20, 20, 1, 255, 0.036, 1, 120, 0, 105, 113501, 2.5, 0, 110, "青春に生きる者を導く、夏の先生。夢へと邁進する聖母の加護が、その身をあらゆる困難から守る。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (21, 21, 1, 350, 0.02, 3, 121, 0, 105, 113401, 2.5, 0, 105, "笑顔の応援が眩しい、夏の超能力　ガール。超能力を駆使して、どんな障害物もひとっ飛びで乗り越える。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (22, 22, 0, 130, 0.018, 1, 122, 1, 105, 110101, 2.5, 0, 110, "海辺で大人の魅力を放つ、夏の　　セクシー先生。その魅力に囚われた対戦相手は、走りを乱してしまう。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (23, 23, 0, 160, 0.03, 3, 123, 0, 111, 110001, 3.5, 1, 105, "水着も絶対外さない、夏のカリスマモデル。走りのバイブスは超テンアゲで、スピードはおにやば。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (24, 24, 0, 130, 0.027, 1, 124, 1, 103, 117201, 1.5, 0, 110, "南の島も盛り上げる、真夏のアイドル。悪天候でも笑顔を絶やさず後半もリズムを上げて走り切る。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (25, 25, 0, 160, 0.02, 2, 125, 0, 108, 117301, 3.5, 1, 105, "海原に美声を響かす、渚の歌姫。　守護の賛歌と精霊の加護により、　障害物から身を守る。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (26, 26, 1, 350, 0.04, 3, 126, 0, 105, 117401, 2.5, 0, 110, "夏でも天邪鬼な、夕凪のテーラー。張り巡らされた魔法の糸で、他の走者の自由を奪う。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (27, 27, 1, 350, 0.009, 1, 127, 0, 105, 117101, 3.5, 0, 110, "向日葵が良く似合う、海辺の　　　お姉ちゃん。秘密結社の一員で、　抜群の身体能力が一番の武器。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (28, 28, 1, 255, 0.022, 1, 128, 0, 105, 122901, 3.5, 0, 120, "渚でおっとり、夏色うさぎっこ。　うさぎさんパワー全開で、ぴょん　ぴょんとコースを跳ね回る。");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (29, 29, 0, 130, 0.028, 3, 129, 1, 105, 122801, 2.5, 0, 110, "無邪気さ弾ける、夏色いたずら娘。砂浜でも、いたずらの準備は万端！レースに大波乱が巻き起こる！？");
INSERT INTO `v1_32e78c77a648855830a4726099402ad6b7637f77ebf105dc039c7f2746480225` VALUES (30, 30, 0, 130, 0.023, 2, 130, 0, 108, 122701, 3.5, 1, 105, "海でも真面目な、夏色優等生。　　高めた魔力を解き放ち、一瞬の内に他の走者を置き去りにする。");
